INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B04_21', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B04'), 'LS6_KNTT_B04', 'Một di chỉ vừa phát hiện răng hoá thạch Người tối cổ vừa có công cụ đá ghè đẽo thô sơ. Kết luận phù hợp nhất', 'di chỉ cung cấp đồng thời bằng chứng về sự hiện diện và hoạt động chế tác công cụ của Người tối cổ', 'di chỉ chứng minh Người tinh khôn đã biết luyện kim và làm đồ gốm ở cùng thời điểm', 'chỉ công cụ đá có giá trị, còn răng hoá thạch không giúp xác định dạng người', 'chỉ răng hoá thạch có giá trị, còn công cụ đá không liên quan đến hoạt động con người', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: di chỉ cung cấp đồng thời bằng chứng về sự hiện diện và hoạt động chế tác công cụ của Người tối cổ') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
