INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B04_23', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B04'), 'LS6_KNTT_B04', 'Một bạn cho rằng “chỉ cần di cốt hoá thạch, công cụ đá không có ý nghĩa khi tìm hiểu nguồn gốc loài người”. Đánh giá phù hợp', 'đúng, vì công cụ đá chỉ phản ánh tự nhiên chứ không liên quan đến con người', 'đúng, vì mọi công cụ đá đều do tự nhiên tạo ra và không phải chứng cứ lịch sử', 'không đúng, vì công cụ đá cùng di cốt hoá thạch là những bằng chứng quan trọng về người cổ', 'không đúng, vì chỉ công cụ đá mới xác định được chính xác hình dạng cơ thể của người cổ', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: không đúng, vì công cụ đá cùng di cốt hoá thạch là những bằng chứng quan trọng về người cổ') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B04_24', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B04'), 'LS6_KNTT_B04', 'Kết luận khái quát phù hợp nhất từ các dấu tích ở Đông Nam Á và Việt Nam', 'Đông Nam Á không có dấu tích Vượn người nên không liên quan đến tiến hoá loài người', 'Việt Nam chỉ có công cụ đá mà chưa từng tìm thấy di cốt hoá thạch người cổ', 'mọi dấu tích trong khu vực đều thuộc cùng một thời điểm và cùng một dạng người', 'Đông Nam Á, trong đó có Việt Nam, là khu vực có con người sinh sống sớm và để lại dấu tích qua nhiều giai đoạn', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Đông Nam Á, trong đó có Việt Nam, là khu vực có con người sinh sống sớm và để lại dấu tích qua nhiều giai đoạn') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
