INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B05_15', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B05'), 'LS6_KNTT_B05', 'So với Người tối cổ, đời sống vật chất của Người tinh khôn tiến bộ rõ ở việc', 'tiếp tục chỉ dùng công cụ đá ghè đẽo và dựa hoàn toàn vào hái lượm', 'ngừng chế tạo công cụ để tận dụng hoàn toàn những vật có sẵn trong tự nhiên', 'biết mài đá, làm gốm, dệt vải, trồng trọt và chăn nuôi', 'sử dụng rộng rãi kim loại, tiền tệ và phương tiện vận tải đường dài', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: biết mài đá, làm gốm, dệt vải, trồng trọt và chăn nuôi') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B05_16', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B05'), 'LS6_KNTT_B05', 'Việc tạo ra lửa và phát minh cung tên cho thấy lao động đã', 'làm con người lệ thuộc hơn vào những nguồn thức ăn có sẵn', 'khiến các nhóm người giảm hợp tác và chuyển sang sinh sống riêng lẻ', 'làm cho hoạt động kiếm sống chỉ còn dựa vào săn bắt thú rừng', 'giúp con người cải tiến phương tiện kiếm sống và tăng khả năng chế ngự tự nhiên', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: giúp con người cải tiến phương tiện kiếm sống và tăng khả năng chế ngự tự nhiên') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B05_17', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B05'), 'LS6_KNTT_B05', 'Đồ trang sức và tranh vẽ trên vách hang của người nguyên thủy phản ánh', 'con người đã có nhu cầu thẩm mĩ và đời sống tinh thần bước đầu phát triển', 'con người đã hình thành quân đội chuyên nghiệp và những nghi lễ nhà nước', 'các cộng đồng đã sử dụng chữ viết để ghi chép đầy đủ đời sống hằng ngày', 'hoạt động sản xuất đã chuyển hoàn toàn từ săn bắt sang luyện kim và buôn bán', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: con người đã có nhu cầu thẩm mĩ và đời sống tinh thần bước đầu phát triển') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B05_18', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B05'), 'LS6_KNTT_B05', 'Tục chôn người chết và thờ thần linh ở công xã thị tộc cho thấy', 'con người đã sáng tạo ra hệ thống chữ viết để truyền lại tín ngưỡng', 'đời sống tinh thần phong phú hơn và xuất hiện những quan niệm tín ngưỡng', 'xã hội đã phân hóa sâu sắc và hình thành những giai cấp đối kháng', 'mọi cộng đồng đều theo một tôn giáo thống nhất có tổ chức chặt chẽ', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: đời sống tinh thần phong phú hơn và xuất hiện những quan niệm tín ngưỡng') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B05_19', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B05'), 'LS6_KNTT_B05', 'Tại các di chỉ Hòa Bình, Bắc Sơn, việc cùng tìm thấy công cụ đá mài, đồ gốm, xương gia súc và dấu vết hạt cây cho phép nhận xét', 'cư dân chỉ sống bằng săn bắt thú rừng và chưa biết chế biến thức ăn', 'cư dân đã dùng phổ biến kim loại và chuyển sang sản xuất thủ công quy mô lớn', 'cư dân kết hợp nhiều hoạt động kiếm sống và bước đầu biết làm nông nghiệp', 'cư dân đã xây dựng các đô thị và tổ chức xã hội thành những nhà nước cổ đại', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: cư dân kết hợp nhiều hoạt động kiếm sống và bước đầu biết làm nông nghiệp') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B05_20', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B05'), 'LS6_KNTT_B05', 'Ý nghĩa khái quát của lao động đối với quá trình phát triển xã hội nguyên thủy', 'chỉ làm thay đổi hình dáng công cụ mà không ảnh hưởng đến con người và cộng đồng', 'chỉ giúp con người có thêm thức ăn nhưng không làm thay đổi cách thức tổ chức xã hội', 'chủ yếu tạo ra của cải riêng và thúc đẩy từng cá nhân tách khỏi cộng đồng nguyên thủy', 'góp phần hoàn thiện con người, gắn kết cộng đồng, đổi mới công cụ và nâng cao đời sống', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: góp phần hoàn thiện con người, gắn kết cộng đồng, đổi mới công cụ và nâng cao đời sống') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B05_21', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B05'), 'LS6_KNTT_B05', 'Một di chỉ mới phát hiện có rìu đá mài, đồ gốm, xương gia súc và nhiều hạt cây ăn được. Nhận định phù hợp nhất', 'cư dân đã ở giai đoạn tiến bộ hơn, bước đầu phát triển trồng trọt và chăn nuôi', 'cư dân vẫn chỉ dựa vào hái lượm, chưa có hoạt động sản xuất thức ăn', 'cư dân đã bước vào thời đại kim loại và hình thành nhà nước có giai cấp', 'cư dân chủ yếu sống bằng thương mại và trao đổi sản phẩm giữa các đô thị', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: cư dân đã ở giai đoạn tiến bộ hơn, bước đầu phát triển trồng trọt và chăn nuôi') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B05_22', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B05'), 'LS6_KNTT_B05', 'Chuỗi biến đổi từ công cụ đá ghè đẽo đến đá mài, đồ gốm rồi trồng trọt, chăn nuôi cho phép rút ra kết luận', 'công cụ sản xuất thay đổi nhưng đời sống và tổ chức xã hội hầu như không biến chuyển', 'tiến bộ của công cụ và phương thức sản xuất gắn với quá trình phát triển của xã hội', 'sản xuất nông nghiệp xuất hiện trước khi con người biết cải tiến công cụ lao động', 'đời sống tinh thần quyết định hoàn toàn sự thay đổi của kĩ thuật và phương thức sản xuất', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: tiến bộ của công cụ và phương thức sản xuất gắn với quá trình phát triển của xã hội') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B05_23', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B05'), 'LS6_KNTT_B05', 'Khi thực hành mô phỏng chế tác công cụ đá, học sinh nhận thấy phải lặp lại nhiều thao tác và phối hợp với nhau. Liên hệ phù hợp với vai trò của lao động', 'lao động chủ yếu làm tăng số lượng sản phẩm nhưng không ảnh hưởng đến kĩ năng của con người', 'lao động làm các cá nhân ngày càng tách biệt nên không liên quan đến sự hình thành cộng đồng', 'lao động vừa rèn luyện kĩ năng cơ thể vừa thúc đẩy hợp tác, sáng tạo trong cộng đồng', 'lao động chỉ có ý nghĩa khi con người đã biết dùng kim loại và có tổ chức nhà nước', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: lao động vừa rèn luyện kĩ năng cơ thể vừa thúc đẩy hợp tác, sáng tạo trong cộng đồng') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B05_24', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B05'), 'LS6_KNTT_B05', 'Khi nghiên cứu một địa điểm có công cụ đá, đồ trang sức, tranh vẽ và mộ táng, cách khai thác tư liệu phù hợp nhất', 'chỉ dựa vào công cụ đá để kết luận toàn bộ đời sống của cư dân tại địa điểm', 'chỉ dựa vào tranh vẽ để xác định chính xác mọi hoạt động sản xuất của cư dân', 'chỉ dựa vào mộ táng để xác định đầy đủ cơ cấu tổ chức xã hội của cộng đồng', 'đối chiếu nhiều loại di vật để nhận xét đồng thời đời sống vật chất và tinh thần', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: đối chiếu nhiều loại di vật để nhận xét đồng thời đời sống vật chất và tinh thần') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
