INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B11_21', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B11'), 'LS6_KNTT_B11', 'Một di chỉ ở Đông Nam Á phát hiện gốm Hán, chữ Phạn và hiện vật kiểu La Mã. Kết luận có cơ sở nhất', 'di chỉ từng tham gia mạng lưới giao lưu rộng với nhiều trung tâm bên ngoài', 'di chỉ chỉ có quan hệ với Trung Quốc và không tiếp xúc các khu vực khác', 'toàn bộ hiện vật đều được cư dân bản địa chế tạo theo cùng một truyền thống', 'các dấu tích chứng minh hoạt động thương mại đường biển chưa xuất hiện', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: di chỉ từng tham gia mạng lưới giao lưu rộng với nhiều trung tâm bên ngoài') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B11_22', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B11'), 'LS6_KNTT_B11', 'Kết hợp vị trí địa lí, khí hậu và hoạt động kinh tế, mối quan hệ phù hợp nhất đối với sự hình thành quốc gia sơ kì', 'khí hậu khô hạn tạo du mục, từ đó hình thành các thương cảng ven biển', 'vị trí biệt lập làm giảm giao lưu, từ đó thúc đẩy tổ chức nhà nước tập trung', 'lúa nước và thủ công tạo nền tảng kinh tế, giao lưu bổ sung động lực phát triển', 'giao thương quốc tế thay thế hoàn toàn nông nghiệp và thủ công trong quá trình hình thành', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: lúa nước và thủ công tạo nền tảng kinh tế, giao lưu bổ sung động lực phát triển') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B11_23', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B11'), 'LS6_KNTT_B11', 'Trên lược đồ, nhiều quốc gia sơ kì xuất hiện ở lưu vực sông và vùng ven biển. Giải thích hợp lí nhất', 'những nơi này hoàn toàn không có thiên tai nên cư dân tập trung đông', 'các khu vực này chỉ thuận lợi cho quân sự, ít liên quan đến sản xuất và trao đổi', 'cư dân chỉ chọn nơi gần biển, không phụ thuộc đất đai và nguồn nước', 'nguồn nước, phù sa và giao thông thuận lợi hỗ trợ định cư, sản xuất và trao đổi', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: nguồn nước, phù sa và giao thông thuận lợi hỗ trợ định cư, sản xuất và trao đổi') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B11_24', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B11'), 'LS6_KNTT_B11', 'Từ các bằng chứng thương mại và sự tiếp nhận chữ viết, kĩ thuật, tư tưởng, đánh giá phù hợp nhất', 'giao lưu khiến các cộng đồng Đông Nam Á mất hoàn toàn nền tảng văn hóa bản địa', 'giao lưu vừa thúc đẩy kinh tế vừa mở rộng tiếp xúc văn hóa và hỗ trợ phát triển nhà nước', 'giao lưu chỉ có ý nghĩa với hàng hóa, không tác động đến đời sống tinh thần và tổ chức', 'giao lưu làm các quốc gia sơ kì phụ thuộc hoàn toàn vào một trung tâm văn minh duy nhất', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: giao lưu vừa thúc đẩy kinh tế vừa mở rộng tiếp xúc văn hóa và hỗ trợ phát triển nhà nước') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
