INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B13_22', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B13'), 'LS6_KNTT_B13', 'Một cộng đồng dùng chữ phát triển từ hệ chữ Ấn Độ và phỏng tác Ra-ma-ya-na; cộng đồng khác dùng chữ Hán nhưng vẫn duy trì tín ngưỡng dân gian. Nhận xét phù hợp', 'cả hai cộng đồng đều tiếp nhận cùng một nguồn ảnh hưởng và có biểu hiện giống nhau', 'ảnh hưởng văn hóa khác nhau theo quan hệ tiếp xúc nhưng đều được dung hợp với nền tảng bản địa', 'cộng đồng dùng chữ Hán không còn duy trì bất cứ yếu tố văn hóa bản địa nào', 'cộng đồng phỏng tác Ra-ma-ya-na đã sao chép nguyên vẹn văn hóa Ấn Độ', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: ảnh hưởng văn hóa khác nhau theo quan hệ tiếp xúc nhưng đều được dung hợp với nền tảng bản địa') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B13_23', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B13'), 'LS6_KNTT_B13', 'Khi giới thiệu khu di tích Mỹ Sơn, cách trình bày phù hợp nhất với tinh thần bài học', 'chỉ xem công trình là bản sao kiến trúc Ấn Độ và bỏ qua yếu tố địa phương', 'chỉ nhấn mạnh kĩ thuật xây dựng và không đề cập ý nghĩa tôn giáo', 'khẳng định công trình hoàn toàn không liên quan đến giao lưu văn hóa khu vực', 'làm rõ ảnh hưởng Ấn Độ giáo đồng thời nhấn mạnh sự sáng tạo của cư dân Chăm-pa', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: làm rõ ảnh hưởng Ấn Độ giáo đồng thời nhấn mạnh sự sáng tạo của cư dân Chăm-pa') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
