INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B16_18', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B16'), 'LS6_KNTT_B16', 'Việc khởi nghĩa Mai Thúc Loan thu hút đông đảo nhân dân và được Chăm-pa, Chân Lạp hưởng ứng phản ánh', 'phong trào chỉ có mục tiêu bảo vệ quyền lợi riêng của một nhóm hào trưởng địa phương', 'sự bất bình với ách đô hộ lan rộng và nghĩa quân có khả năng tập hợp nhiều lực lượng', 'nhà Đường chủ động liên minh với các lực lượng trong khu vực để hỗ trợ cuộc khởi nghĩa', 'phạm vi hoạt động của nghĩa quân bị giới hạn hoàn toàn trong khu vực Hoan Châu', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: sự bất bình với ách đô hộ lan rộng và nghĩa quân có khả năng tập hợp nhiều lực lượng') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B16_19', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B16'), 'LS6_KNTT_B16', 'Việc nghĩa quân Mai Thúc Loan giành và giữ quyền tự chủ trong khoảng gần mười năm có ý nghĩa', 'chứng minh nhà Đường đã chấm dứt hoàn toàn việc cai trị đất nước từ đầu thế kỉ VIII', 'cho thấy các cuộc khởi nghĩa trước đó không để lại ảnh hưởng đối với tinh thần đấu tranh', 'đánh dấu một cột mốc quan trọng trên con đường đấu tranh đi đến giải phóng đất nước', 'khẳng định từ năm 713 đất nước đã độc lập liên tục và không còn bị phương Bắc xâm lược', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: đánh dấu một cột mốc quan trọng trên con đường đấu tranh đi đến giải phóng đất nước') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B16_20', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B16'), 'LS6_KNTT_B16', 'Việc nghĩa quân Phùng Hưng làm chủ Tống Bình và duy trì quyền tự chủ khoảng chín năm cho thấy', 'phong trào chỉ nhằm tranh giành quyền lực giữa các hào trưởng trong cùng một địa phương', 'nghĩa quân không tác động đến bộ máy cai trị của nhà Đường tại trung tâm Giao Châu', 'cuộc khởi nghĩa đã chấm dứt vĩnh viễn thời kì Bắc thuộc ngay từ cuối thế kỉ VIII', 'ý chí giành độc lập vẫn bền bỉ và khả năng tự chủ của người Việt tiếp tục được khẳng định', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: ý chí giành độc lập vẫn bền bỉ và khả năng tự chủ của người Việt tiếp tục được khẳng định') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B16_21', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B16'), 'LS6_KNTT_B16', 'Từ chuỗi các cuộc khởi nghĩa năm 40, 248, 542, 713 và cuối thế kỉ VIII có thể khái quát', 'phong trào đấu tranh diễn ra liên tục, nhiều lần giành quyền tự chủ và từng bước nâng cao năng lực tổ chức', 'các cuộc khởi nghĩa ngày càng thu hẹp, không còn hướng tới giành quyền tự chủ cho người Việt', 'mọi cuộc đấu tranh đều bùng nổ cùng một địa điểm, có diễn biến và kết quả hoàn toàn giống nhau', 'sau khởi nghĩa Hai Bà Trưng, nhân dân ngừng đấu tranh cho đến tận đầu thế kỉ X', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: phong trào đấu tranh diễn ra liên tục, nhiều lần giành quyền tự chủ và từng bước nâng cao năng lực tổ chức') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B16_22', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B16'), 'LS6_KNTT_B16', 'So sánh kết quả khởi nghĩa Hai Bà Trưng với khởi nghĩa Lý Bí, nhận xét phù hợp', 'cả hai đều chỉ giành thắng lợi trong vài tháng và chưa hình thành chính quyền tự chủ', 'cả hai đều giành quyền tự chủ, nhưng Lý Bí tiến thêm một bước khi lập nước Vạn Xuân', 'Hai Bà Trưng lập nước Vạn Xuân, còn Lý Bí chỉ chiếm được một số huyện lị ở Cửu Chân', 'khởi nghĩa Lý Bí diễn ra trước Hai Bà Trưng và không liên hệ với quá trình giành tự chủ', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: cả hai đều giành quyền tự chủ, nhưng Lý Bí tiến thêm một bước khi lập nước Vạn Xuân') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B16_23', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B16'), 'LS6_KNTT_B16', 'Kết hợp lược đồ khởi nghĩa Hai Bà Trưng và Mai Thúc Loan, có thể nhận xét về cách phát triển lực lượng', 'cả hai phong trào chỉ giữ quân ở căn cứ ban đầu và tránh tiến tới trung tâm cai trị', 'cả hai phong trào đều dựa hoàn toàn vào viện binh bên ngoài để mở rộng địa bàn hoạt động', 'nghĩa quân xuất phát từ căn cứ địa phương rồi mở rộng tiến công tới các trung tâm của chính quyền đô hộ', 'nghĩa quân chủ yếu rút lui khỏi đồng bằng và không tranh giành các trị sở quan trọng', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: nghĩa quân xuất phát từ căn cứ địa phương rồi mở rộng tiến công tới các trung tâm của chính quyền đô hộ') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B16_24', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B16'), 'LS6_KNTT_B16', 'Một ý kiến cho rằng các cuộc khởi nghĩa trước thế kỉ X đều thất bại nên không có giá trị đối với lịch sử dân tộc, nhận xét phù hợp', 'ý kiến đúng vì mọi cuộc khởi nghĩa đều kết thúc ngay khi vừa bùng nổ và không tạo ảnh hưởng', 'ý kiến đúng vì nhân dân không từng giành được quyền tự chủ trong suốt thời kì Bắc thuộc', 'ý kiến chưa đủ vì chỉ khởi nghĩa Lý Bí có ý nghĩa, còn các phong trào khác không để lại dấu ấn', 'ý kiến không phù hợp vì các cuộc khởi nghĩa nuôi dưỡng ý chí độc lập và tích lũy kinh nghiệm đấu tranh', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: ý kiến không phù hợp vì các cuộc khởi nghĩa nuôi dưỡng ý chí độc lập và tích lũy kinh nghiệm đấu tranh') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
