INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B17_22', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B17'), 'LS6_KNTT_B17', 'Từ tư liệu “Dân hay vẽ mình... Tiếp khách thì đãi trầu cau”, kết luận phù hợp nhất', 'người Việt đã từ bỏ phong tục bản địa và chuyển hẳn sang cách sống của người Hán', 'tư liệu chỉ phản ánh hoạt động kinh tế nên không cho biết đặc điểm văn hóa cộng đồng', 'tục vẽ mình và ăn trầu chỉ xuất hiện sau khi các triều đại phương Bắc chấm dứt cai trị', 'một số phong tục bản địa vẫn hiện diện rõ trong đời sống người Việt thời Bắc thuộc', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: một số phong tục bản địa vẫn hiện diện rõ trong đời sống người Việt thời Bắc thuộc') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B17_23', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B17'), 'LS6_KNTT_B17', 'Đặt dữ kiện “nghe và nói bằng tiếng Việt” cạnh dữ kiện “tiếp thu chữ Hán”, nhận xét phù hợp', 'người Việt vừa bảo tồn tiếng mẹ đẻ vừa sử dụng có chọn lọc một công cụ văn hóa từ bên ngoài', 'người Việt dùng chữ Hán nên tiếng Việt nhanh chóng mất vai trò trong đời sống cộng đồng', 'hai dữ kiện cho thấy người Việt hoàn toàn khép kín và không tiếp nhận ảnh hưởng từ Trung Hoa', 'hai dữ kiện chứng minh chính sách đồng hóa đã làm văn hóa bản địa biến mất trong thời Bắc thuộc', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: người Việt vừa bảo tồn tiếng mẹ đẻ vừa sử dụng có chọn lọc một công cụ văn hóa từ bên ngoài') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
