INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B18_14', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B18'), 'LS6_KNTT_B18', 'Nguyên nhân giúp các cải cách của Khúc Hạo góp phần củng cố nền tự chủ', 'các biện pháp đều nhằm tăng lao dịch và tập trung quyền thu thuế vào quan lại', 'chủ trương khoan dung, giản dị, giảm gánh nặng và hướng tới làm dân yên vui', 'cải cách đặt trọng tâm vào việc mở rộng bộ máy cai trị của phong kiến phương Bắc', 'chính quyền xóa bỏ quản lí hộ khẩu nên không còn kiểm soát được dân cư địa phương', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: chủ trương khoan dung, giản dị, giảm gánh nặng và hướng tới làm dân yên vui') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B18_15', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B18'), 'LS6_KNTT_B18', 'Ý nghĩa trực tiếp của thắng lợi do Dương Đình Nghệ lãnh đạo năm 931', 'đánh đuổi quân Nam Hán, khôi phục và tiếp tục củng cố nền tự chủ của người Việt', 'mở đầu thời kì Bắc thuộc và đặt Giao Châu dưới quyền cai trị của Nam Hán', 'chấm dứt hoàn toàn mọi nguy cơ xâm lược từ phương Bắc trong các thế kỉ sau', 'thành lập ngay một vương triều mới với quốc hiệu và niên hiệu độc lập', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: đánh đuổi quân Nam Hán, khôi phục và tiếp tục củng cố nền tự chủ của người Việt') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B18_16', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B18'), 'LS6_KNTT_B18', 'Mối quan hệ giữa hoạt động của họ Khúc và sự nghiệp của Dương Đình Nghệ', 'hai quá trình diễn ra tách biệt, không cùng mục tiêu giành và giữ quyền tự chủ', 'họ Khúc chủ trương lệ thuộc còn Dương Đình Nghệ mới bắt đầu đấu tranh giành độc lập', 'Dương Đình Nghệ nối tiếp sự nghiệp của họ Khúc, đánh giặc và củng cố nền tự chủ', 'Dương Đình Nghệ thay thế toàn bộ thành quả của họ Khúc bằng bộ máy cai trị Nam Hán', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Dương Đình Nghệ nối tiếp sự nghiệp của họ Khúc, đánh giặc và củng cố nền tự chủ') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B18_17', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B18'), 'LS6_KNTT_B18', 'Điều kiện khiến sông Bạch Đằng trở thành địa bàn thuận lợi để Ngô Quyền tổ chức trận quyết chiến', 'lòng sông luôn cạn, không có thủy triều và tàu chiến lớn không thể đi vào', 'đây là đường thủy quan trọng, thủy triều chênh lệch lớn và địa hình thuận lợi bố trí mai phục', 'khu vực hoàn toàn trống trải, ít nhánh sông nên quân giặc dễ bị quan sát từ xa', 'sông nằm sâu trong nội địa, tách biệt với đường tiến quân bằng biển của quân Nam Hán', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: đây là đường thủy quan trọng, thủy triều chênh lệch lớn và địa hình thuận lợi bố trí mai phục') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B18_18', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B18'), 'LS6_KNTT_B18', 'Cách trận địa cọc Bạch Đằng phát huy hiệu quả trong kế hoạch của Ngô Quyền', 'cọc được dựng nổi từ đầu để buộc thuyền giặc dừng lại ngay ngoài cửa biển', 'quân ta phá cọc khi nước lên để tạo đường cho thuyền giặc tiến sâu vào đất liền', 'cọc chỉ dùng làm mốc dẫn đường cho quân ta và không tham gia trực tiếp vào trận đánh', 'cọc ngầm khi triều lên, lộ ra khi nước rút khiến thuyền giặc mắc kẹt trong lúc quân ta phản công', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: cọc ngầm khi triều lên, lộ ra khi nước rút khiến thuyền giặc mắc kẹt trong lúc quân ta phản công') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B18_19', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B18'), 'LS6_KNTT_B18', 'Mục đích của việc Ngô Quyền cho thuyền nhẹ ra khiêu chiến rồi giả thua chạy', 'đưa toàn bộ lực lượng ta ra biển xa để tránh giao chiến ở cửa sông', 'tạo điều kiện cho quân Nam Hán rút khỏi vùng cửa sông mà không phải giao chiến', 'nhử quân Hoằng Tháo tiến sâu vào khu vực trận địa cọc khi nước triều đang lên', 'kéo dài thời gian để chờ viện binh từ các lực lượng bên ngoài tiến đến hỗ trợ', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: nhử quân Hoằng Tháo tiến sâu vào khu vực trận địa cọc khi nước triều đang lên') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B18_20', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B18'), 'LS6_KNTT_B18', 'Ý nghĩa lịch sử quan trọng nhất của chiến thắng Bạch Đằng năm 938', 'chấm dứt thời kì Bắc thuộc và mở ra kỉ nguyên độc lập, tự chủ lâu dài cho dân tộc', 'buộc nhà Nam Hán phải chuyển kinh đô và từ bỏ toàn bộ lãnh thổ ở phía nam Trung Quốc', 'mở đầu quá trình người Việt giành quyền tự chủ nhưng chưa kết thúc thời kì Bắc thuộc', 'chỉ bảo vệ được vùng cửa sông Bạch Đằng mà chưa làm thay đổi cục diện lịch sử dân tộc', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: chấm dứt thời kì Bắc thuộc và mở ra kỉ nguyên độc lập, tự chủ lâu dài cho dân tộc') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B18_21', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B18'), 'LS6_KNTT_B18', 'Nhận xét phù hợp nhất về điểm độc đáo trong cách tổ chức đánh giặc của Ngô Quyền', 'chủ động tránh mọi trận thủy chiến và chỉ dựa vào lực lượng bộ binh trên bờ', 'chọn cách đối đầu trực diện với hạm đội địch ngay từ ngoài biển khi nước chưa lên', 'kết hợp phân tích địch, bố trí phục kích, lợi dụng địa hình và quy luật thủy triều để phản công', 'chỉ dựa vào bãi cọc có sẵn trong tự nhiên, không cần tổ chức nhử địch hay phối hợp lực lượng', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: kết hợp phân tích địch, bố trí phục kích, lợi dụng địa hình và quy luật thủy triều để phản công') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B18_22', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B18'), 'LS6_KNTT_B18', 'So sánh vai trò của họ Khúc, họ Dương với chiến thắng Bạch Đằng năm 938, nhận xét phù hợp', 'họ Khúc và họ Dương gây dựng, bảo vệ nền tự chủ; Bạch Đằng 938 hoàn tất bước chuyển sang độc lập lâu dài', 'họ Khúc đã chấm dứt hoàn toàn Bắc thuộc nên chiến thắng Bạch Đằng chỉ mang ý nghĩa quân sự địa phương', 'Dương Đình Nghệ mở đầu thời Bắc thuộc còn Ngô Quyền tiếp tục duy trì bộ máy cai trị của Nam Hán', 'cả ba lực lượng đều chỉ giành thắng lợi tạm thời, chưa tạo ra bước chuyển về vị thế chính trị của dân tộc', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: họ Khúc và họ Dương gây dựng, bảo vệ nền tự chủ; Bạch Đằng 938 hoàn tất bước chuyển sang độc lập lâu dài') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B18_23', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B18'), 'LS6_KNTT_B18', 'Từ việc Ngô Quyền tính toán mực nước, bãi cọc, việc nhử địch và thời điểm phản công, có thể rút ra kết luận', 'chiến thắng chủ yếu do quân Nam Hán tự rút lui nên việc chuẩn bị của quân ta không giữ vai trò đáng kể', 'trận đánh không cần phối hợp thời gian vì cọc gỗ có thể phát huy tác dụng ở mọi trạng thái thủy triều', 'Ngô Quyền chỉ sử dụng kinh nghiệm có sẵn, không điều chỉnh kế hoạch theo địa hình và tình hình đối phương', 'kế hoạch đòi hỏi sự phối hợp chính xác giữa địa hình, thủy triều, nghi binh, phục kích và thời cơ phản công', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: kế hoạch đòi hỏi sự phối hợp chính xác giữa địa hình, thủy triều, nghi binh, phục kích và thời cơ phản công') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B18_24', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B18'), 'LS6_KNTT_B18', 'Đánh giá ý kiến cho rằng chiến thắng Bạch Đằng năm 938 chỉ do có bãi cọc ngầm', 'ý kiến phù hợp vì bãi cọc tự động tiêu diệt hạm đội địch mà không cần lực lượng quân ta tham chiến', 'ý kiến chưa đầy đủ vì thắng lợi là kết quả của kế hoạch chủ động kết hợp trận địa, thủy triều và lực lượng', 'ý kiến phù hợp vì Ngô Quyền không cần nghiên cứu đối phương, chỉ cần chọn cửa sông có bãi cọc tự nhiên', 'ý kiến chưa đủ vì yếu tố quyết định duy nhất lại là số lượng thuyền nhẹ dùng để khiêu chiến với quân Nam Hán', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: ý kiến chưa đầy đủ vì thắng lợi là kết quả của kế hoạch chủ động kết hợp trận địa, thủy triều và lực lượng') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
