INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B20_TF01', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B20'), 'LS6_KNTT_B20', 'Không chỉ trao đổi hàng hóa tiêu dùng trong nước, người Phù Nam còn buôn bán với các thương nhân nước ngoài đến từ Trung Quốc, Mã Lai, Ấn Độ,… thông qua thương cảng Óc Eo. (Đúng hay Sai?)', 'Đúng', 'Sai', NULL, NULL, 1, 20, 'WARM_UP', 'EASY', 'Nhận định này là ĐÚNG.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
